-- Portail territorial : catalogues persistants des tableaux et exports.
-- Aucun changement des territoires, références, clés étrangères ou préférences personnelles.
-- Rejouable : les définitions déjà présentes sont conservées, sans écrasement des personnalisations.
BEGIN;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';
ALTER TABLE referentiel."T_InterfaceTableau" DROP CONSTRAINT IF EXISTS "ck_interface_tableau_module";
ALTER TABLE referentiel."T_InterfaceTableau" ADD CONSTRAINT "ck_interface_tableau_module"
 CHECK ("Module" IN ('logistique','referentiels','administration','territoires'));
COMMENT ON CONSTRAINT "ck_interface_tableau_module" ON referentiel."T_InterfaceTableau"
 IS 'Applications couvertes par les catalogues persistants de tableaux et exports, dont Organisation territoriale. Les droits sont vérifiés par chaque service source.';

